<section class="section projects-section" id="projetos"><div class="section-heading"><p class="eyebrow">04 / PROJETOS</p><h2>Ideias em<br><em>construção.</em></h2><p>Estudos demonstrativos para explorar problemas, interfaces e possibilidades técnicas.</p></div><div class="project-tools"><label class="search-field">Buscar <input id="project-search" type="search" placeholder="Nome, tecnologia ou categoria"></label><label>Categoria <select id="project-category"><option value="all">Todas</option><?php foreach(array_unique(array_column($c['projects'],'category')) as $cat): ?><option><?=e($cat)?></option><?php endforeach; ?></select></label><label>Tecnologia <select id="project-tech"><option value="all">Todas</option><?php foreach(array_unique(array_merge(...array_column($c['projects'],'technologies'))) as $tech): ?><option><?=e($tech)?></option><?php endforeach; ?></select></label></div><div class="project-grid" id="project-grid"><?php foreach($c['projects'] as $p): ?><article class="project-card" data-project data-category="<?=e($p['category'])?>" data-tech="<?=e(implode('|',$p['technologies']))?>"><div class="project-art" aria-hidden="true"><span class="art-grid"></span><span class="art-frame"></span><span class="art-code">RP / <?=e(strtoupper(substr($p['id'],0,3)))?></span></div><div class="project-body"><p class="eyebrow"><?=e($p['category'])?> · <?=e($p['type'])?></p><h3><?=e($p['name'])?></h3><p><?=e($p['description'])?></p><div class="tag-list"><?php foreach($p['technologies'] as $t): ?><span><?=e($t)?></span><?php endforeach; ?></div><button class="text-link project-open" data-project-id="<?=e($p['id'])?>">Ver detalhes <span>↗</span></button></div><script type="application/json" class="project-data"><?=json_encode($p,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script></article><?php endforeach; ?></div><p class="empty-state" id="project-empty" hidden>Nenhum projeto corresponde aos filtros.</p><dialog class="project-dialog" id="project-dialog"><button class="dialog-close" aria-label="Fechar detalhes">×</button><div id="project-dialog-content"></div></dialog></section>
